import java.util.ArrayList;
import java.util.List;
import java.util.ListIterator;

public class ListIteratorDemo {
    public static void main(String[] args) {
        List<String> pipeline = new ArrayList<>();
        pipeline.add("STAGE_ONE");
        pipeline.add("LEGACY_STAGE");
        pipeline.add("STAGE_THREE");

        ListIterator<String> iterator = pipeline.listIterator();

        while (iterator.hasNext()) {
            String current = iterator.next();
            if ("LEGACY_STAGE".equals(current)) {
                // Replace element in-place without structural corruption
                iterator.set("MODERN_STAGE");
                // Insert a new element immediately after the cursor
                iterator.add("NEW_INJECTED_STAGE");
            }
        }

        // Traverse backwards to verify state
        while (iterator.hasPrevious()) {
            System.out.println(iterator.previous());
        }
    }
}
